WITH product_summary AS (SELECT product_id, MAX(quantity) - MIN(quantity) AS quantity_range, AVG(quantity) AS avg_quantity FROM inventory GROUP BY product_id) SELECT p.id, p.price, p.cost, ps.quantity_range, ps.avg_quantity FROM products p INNER JOIN product_summary ps ON p.id = ps.product_id WHERE ps.avg_quantity >= 190 ORDER BY p.cost DESC
